mapper.select:
SELECT s.id AS shareId, q.title, qv.id AS versionId, qv.question_kind AS questionKind, qv.stem, qv.options_json AS optionsJson, qv.answer_json AS answerJson, qv.explanation, qv.difficulty, qv.tags, qv.max_score AS maxScore, s.import_count AS importCount, DATE_FORMAT(s.shared_at, '%Y-%m-%dT%H:%i:%s.000Z') AS sharedAt, cs.title AS sourceCourseTitle, COALESCE(u.nick_name, u.user_name) AS sharedByName, college.dept_id AS collegeId, college.dept_name AS collegeName, (SELECT GROUP_CONCAT(kp.name ORDER BY kp.name SEPARATOR '、') FROM edu_question_knowledge_point qkp JOIN edu_knowledge_point kp ON kp.id = qkp.knowledge_point_id WHERE qkp.question_id = q.id) AS knowledgePoints FROM edu_question_share s JOIN edu_question_version qv ON qv.id = s.question_version_id JOIN edu_question q ON q.id = qv.question_id LEFT JOIN edu_course_space cs ON cs.id = s.source_course_space_id LEFT JOIN sys_user u ON u.user_id = s.shared_by_user_id LEFT JOIN sys_dept d ON d.dept_id = u.dept_id LEFT JOIN sys_dept college ON college.dept_id = COALESCE( (SELECT cd.dept_id FROM sys_dept cd WHERE cd.dept_type = 'COLLEGE' AND (cd.dept_id = d.dept_id OR FIND_IN_SET(cd.dept_id, d.ancestors)) ORDER BY cd.dept_id LIMIT 1), d.dept_id) WHERE s.status = 'PUBLISHED'
AND (q.title LIKE CONCAT('%', #{keyword}, '%') OR qv.stem LIKE CONCAT('%', #{keyword}, '%'))
AND qv.question_kind = #{questionKind}
AND qv.difficulty = #{difficulty}
AND college.dept_id = #{collegeId}
ORDER BY s.shared_at DESC, s.id DESC LIMIT #{limit}

SELECT COUNT(*)
FROM edu_question
WHERE course_space_id = #{courseSpaceId}
  AND origin_share_id = #{shareId}

