mapper.select:
SELECT q.id AS questionId, q.title, qv.id AS versionId, qv.question_kind AS questionKind, qv.stem, qv.options_json AS optionsJson, qv.answer_json AS answerJson, qv.explanation, qv.difficulty, qv.tags, qv.max_score AS maxScore, (SELECT GROUP_CONCAT(kp.name ORDER BY kp.name SEPARATOR '、') FROM edu_question_knowledge_point qkp JOIN edu_knowledge_point kp ON kp.id = qkp.knowledge_point_id WHERE qkp.question_id = q.id) AS knowledgePoints FROM edu_question q JOIN edu_question_version qv ON qv.question_id = q.id AND qv.version_no = (SELECT MAX(v.version_no) FROM edu_question_version v WHERE v.question_id = q.id) WHERE q.course_space_id = #{courseSpaceId} AND q.status <> 'ARCHIVED'
AND qv.question_kind = #{questionKind}
AND qv.difficulty = #{difficulty}
AND qv.tags LIKE CONCAT('%', #{tag}, '%')
AND EXISTS ( SELECT 1 FROM edu_question_knowledge_point qkp JOIN edu_knowledge_point kp ON kp.id = qkp.knowledge_point_id WHERE qkp.question_id = q.id AND kp.name = #{knowledgePoint} )
ORDER BY RAND()
ORDER BY q.created_at DESC, q.id DESC
LIMIT #{count}

