SELECT r.id, r.title, r.category_id AS categoryId, c.name AS categoryName, r.resource_kind AS resourceKind, r.description, r.tags, r.difficulty, r.view_count AS viewCount, r.download_count AS downloadCount, r.rating_avg AS ratingAvg, r.rating_count AS ratingCount, r.status, COALESCE(u.nick_name, u.user_name) AS submitterName, r.submitted_at AS submittedAt, rv.id AS versionId, rv.version_no AS versionNo, rv.mime_type AS mimeType, rv.byte_size AS byteSize, rv.external_uri AS externalUri, rv.processing_status AS processingStatus FROM edu_public_resource r LEFT JOIN edu_public_resource_version rv ON rv.resource_id = r.id AND rv.version_no = (SELECT MAX(v.version_no) FROM edu_public_resource_version v WHERE v.resource_id = r.id) LEFT JOIN edu_public_resource_category c ON c.id = r.category_id LEFT JOIN sys_user u ON u.user_id = r.submitter_user_id WHERE r.status = 'APPROVED'
AND (r.title LIKE CONCAT('%', #{keyword}, '%') OR r.description LIKE CONCAT('%', #{keyword}, '%') OR r.tags LIKE CONCAT('%', #{keyword}, '%'))
AND r.category_id = #{categoryId}
AND r.resource_kind = #{resourceKind}
ORDER BY r.created_at DESC, r.id DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM edu_public_resource r WHERE r.status = 'APPROVED'
AND (r.title LIKE CONCAT('%', #{keyword}, '%') OR r.description LIKE CONCAT('%', #{keyword}, '%') OR r.tags LIKE CONCAT('%', #{keyword}, '%'))
AND r.category_id = #{categoryId}
AND r.resource_kind = #{resourceKind}

